 assert.equal(await lab.locator('[data-survivor-mean]').getAttribute('data-survivor-mean'),String(e.conditionalSurvivorMean??'undefined'));const mass=await lab.locator('[data-path-failure]').evaluate(el=>({p:Number(el.dataset.pathFailure),width:el.getBoundingClientRect().width,track:el.parentElement.clientWidth}));close(mass.p,e.failureProbability);assert(Math.abs(mass.width-mass.track*mass.p)<1.1);for(const g of e.groups){const row=lab.locator(`[data-failure-period="${g.period}"]`),bar=await row.locator('[data-period-failure]').evaluate(el=>({p:el.dataset.periodFailure,width:el.getBoundingClientRect().width,track:el.parentElement.clientWidth}));assert.equal(bar.p,String(g.conditionalFailure??'undefined'));assert((await row.innerText()).includes(`${g.atRisk}경로`));assert((await row.innerText()).includes(`${g.cumulative}/${e.count}`));assert(Math.abs(bar.width-bar.track*(g.conditionalFailure??0))<1.1);}
